import * as THREE from 'three';
import { mat, box, sphere, cylinder, cone } from './kit.js';

/* "SUBJECT 06" — an emaciated, pale humanoid grown in a tank.
   Built from primitives with articulated pivots so it can walk. */
export function buildCreature(parent) {
  const skin = mat('subject skin', 0x9b998b, 1);
  const skinDark = mat('subject skin dark', 0x6e6e61, 1);
  const wound = mat('subject wound', 0x4a1c16, 0.9, { emissive: 0x1c0403, emissiveIntensity: 0.25 });
  const bone = mat('subject bone', 0xc6bfa7, 0.7);
  const cloth = mat('subject cloth', 0x24272a, 1);
  const socket = mat('subject socket', 0x050707, 0.9);
  const eyeMat = mat('subject eye', 0xff5f2c, 0.3, { emissive: 0xff4a1c, emissiveIntensity: 2.5 });

  const root = new THREE.Group();
  root.name = 'SUBJECT 06';
  parent.add(root);
  const body = new THREE.Group();
  root.add(body);

  // pelvis
  sphere(body, 'pelvis', 0, 1.42, 0, 0.25, skinDark, 1, 0.7, 0.78);

  // torso pivot (hunched)
  const torso = new THREE.Group();
  torso.position.set(0, 1.46, 0);
  torso.rotation.x = 0.14;
  body.add(torso);

  cylinder(torso, 'abdomen', 0, 0.33, 0, 0.27, 0.19, 0.7, skin, 10).scale.z = 0.74;
  sphere(torso, 'ribcage', 0, 0.7, 0, 0.33, skin, 1.02, 0.64, 0.7);
  for (const s of [-1, 1]) sphere(torso, 'shoulder', s * 0.35, 0.72, 0, 0.13, skin, 1.35, 0.9, 1);

  // exposed ribs
  for (let i = 0; i < 4; i++) {
    const y = 0.42 + i * 0.1;
    for (const s of [-1, 1]) {
      const rib = box(torso, 'rib', s * (0.1 + i * 0.006), y, 0.17, 0.23 - i * 0.015, 0.026, 0.055, bone);
      rib.rotation.z = s * 0.2;
    }
  }
  box(torso, 'sternum', 0, 0.52, 0.2, 0.035, 0.38, 0.03, bone);
  for (let i = 0; i < 5; i++) sphere(torso, 'spine', 0, 0.18 + i * 0.12, -0.2, 0.035, bone, 1, 1.4, 1);
  for (let i = 0; i < 4; i++) {
    const spike = cone(torso, 'spine spike', 0, 0.24 + i * 0.13, -0.24, 0.035, 0.14, bone, 5);
    spike.rotation.x = -0.7;
  }

  // wounds / growths
  sphere(torso, 'wound', -0.17, 0.55, 0.18, 0.09, wound, 1.4, 0.8, 0.35);
  sphere(torso, 'wound', 0.2, 0.3, 0.12, 0.07, wound, 1.2, 1.4, 0.3);
  sphere(torso, 'growth', 0.13, 0.62, -0.18, 0.08, skinDark, 1, 1.3, 1);

  // neck + collar
  cylinder(torso, 'neck', 0, 0.9, 0.02, 0.095, 0.075, 0.3, skinDark, 8);
  const collar = new THREE.Mesh(new THREE.TorusGeometry(0.115, 0.022, 6, 14), mat('subject collar', 0x6b6f68, 0.4, { metalness: 0.7 }));
  collar.position.set(0, 0.9, 0.02); collar.rotation.x = Math.PI / 2; torso.add(collar);
  const tag = box(torso, 'id tag', 0, 0.84, 0.13, 0.07, 0.09, 0.015, mat('subject tag', 0xb0a989, 0.5, { metalness: 0.4 }));
  tag.rotation.z = 0.15;

  // head
  const head = new THREE.Group();
  head.position.set(0, 1.03, 0.04);
  torso.add(head);
  sphere(head, 'skull', 0, 0.12, 0, 0.24, skin, 0.84, 1.08, 0.92);
  box(head, 'brow', 0, 0.19, 0.17, 0.34, 0.07, 0.09, skinDark);
  for (const s of [-1, 1]) {
    sphere(head, 'eye socket', s * 0.085, 0.1, 0.195, 0.072, socket, 1, 1.1, 0.8);
    sphere(head, 'eye', s * 0.085, 0.1, 0.245, 0.027, eyeMat, 1, 1, 0.7);
    sphere(head, 'cheek', s * 0.16, 0.0, 0.13, 0.055, skinDark, 1, 1.4, 0.7);
  }
  const nose = cone(head, 'nose hole', 0, 0.07, 0.225, 0.028, 0.07, socket, 6);
  nose.rotation.x = Math.PI;
  sphere(head, 'cranium ridge', 0, 0.32, -0.02, 0.13, skinDark, 1.3, 0.6, 1.2);

  const jaw = new THREE.Group();
  jaw.position.set(0, -0.02, 0.02);
  head.add(jaw);
  sphere(jaw, 'jaw bone', 0, -0.09, 0.1, 0.15, skinDark, 1.05, 0.55, 0.95);
  box(jaw, 'mouth cavity', 0, -0.035, 0.19, 0.19, 0.06, 0.035, socket);
  for (let i = 0; i < 5; i++) {
    const tx = -0.07 + i * 0.035;
    const tooth = cone(jaw, 'lower tooth', tx, 0.005, 0.2, 0.014, 0.06, bone, 5);
    tooth.rotation.x = -0.2;
    const upper = cone(head, 'upper tooth', tx, -0.01, 0.205, 0.013, 0.055, bone, 5);
    upper.rotation.x = Math.PI;
  }
  for (let i = 0; i < 6; i++) {
    const strip = box(head, 'skin strip', -0.15 + i * 0.06, -0.06, -0.02, 0.025, 0.22, 0.025, skinDark);
    strip.rotation.z = (i - 2.5) * 0.04;
  }

  // arms
  function makeArm(side) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.36, 0.71, 0);
    torso.add(shoulder);
    sphere(shoulder, 'shoulder joint', 0, 0, 0, 0.105, skin);
    cylinder(shoulder, 'upper arm', 0, -0.32, 0, 0.075, 0.052, 0.64, skin, 8).scale.z = 0.9;
    const elbow = new THREE.Group();
    elbow.position.y = -0.64;
    shoulder.add(elbow);
