export function animateCreature(c, dt, t) {
  const awake = c.awake;
  const speed = awake ? (c.moving ? 7.2 : 2.2) : 0.8;
  c.phase += dt * speed;
  const p = c.phase;
  const breathe = Math.sin(t * 1.4) * 0.012;

  c.body.position.y = Math.sin(p * 1.9) * (awake ? 0.045 : 0.012) + breathe;
  c.torso.rotation.x = (awake ? 0.32 : 0.13) + Math.sin(p * 1.9) * 0.02;
  c.torso.rotation.z = Math.sin(p * 0.9) * (awake ? 0.05 : 0.02);

  c.head.rotation.x = awake ? -0.24 : -0.04;
  c.head.rotation.z = Math.sin(t * 0.73) * (awake ? 0.07 : 0.15) + Math.sin(t * 7.1) * (awake ? 0.035 : 0.006);
  c.head.rotation.y = Math.sin(t * 0.41) * (awake ? 0.08 : 0.14);

  const swing = awake && c.moving ? 0.62 : 0.05;
  c.armL.shoulder.rotation.x = Math.sin(p) * swing - (awake ? 0.28 : 0.04);
  c.armR.shoulder.rotation.x = -Math.sin(p) * swing - (awake ? 0.28 : 0.04);
  c.armL.shoulder.rotation.z = 0.14 + (awake ? 0.08 : 0);
  c.armR.shoulder.rotation.z = -0.14 - (awake ? 0.08 : 0);
  c.armL.elbow.rotation.x = awake ? -0.55 + Math.sin(p) * 0.16 : -0.06;
  c.armR.elbow.rotation.x = awake ? -0.55 - Math.sin(p) * 0.16 : -0.06;

  const legSwing = awake && c.moving ? 0.62 : 0.03;
  c.legL.hip.rotation.x = Math.sin(p) * legSwing;
  c.legR.hip.rotation.x = -Math.sin(p) * legSwing;
  c.legL.knee.rotation.x = 0.08 + Math.max(0, -Math.sin(p)) * (awake ? 0.75 : 0.05);
  c.legR.knee.rotation.x = 0.08 + Math.max(0, Math.sin(p)) * (awake ? 0.75 : 0.05);

  c.jaw.rotation.x = (awake ? 0.3 : 0.05) + (awake ? Math.sin(t * 5.3) * 0.12 : 0.01);
  c.eyes.emissiveIntensity = awake ? 2.2 + Math.sin(t * 8) * 0.8 : 1.0;

  for (let i = 0; i < c.strips.length; i++) {
    c.strips[i].rotation.z = Math.sin(t * 1.3 + i) * (awake ? 0.1 : 0.04);
  }
}

