+
+  function walkableNear(ix, iz) {
+    if (PATH.walk[iz * PATH.w + ix]) return [ix, iz];
+    for (let r = 1; r <= 5; r++) for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
+      if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
+      const nx = ix + dx, nz = iz + dz;
