631:   function findPath(sx, sz, tx, tz) {
632:     if (!PATH.walk) return null;
633:     const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
634:     const six = clamp(Math.round(sx - PATH.x0), 0, PATH.w - 1);
635:     const siz = clamp(Math.round(sz - PATH.z0), 0, PATH.h - 1);
636:     const tix = clamp(Math.round(tx - PATH.x0), 0, PATH.w - 1);
637:     const tiz = clamp(Math.round(tz - PATH.z0), 0, PATH.h - 1);
638:     const start = walkableNear(six, siz), goal = walkableNear(tix, tiz);
639:     if (!start || !goal) return null;
640:     const w = PATH.w, h = PATH.h;
641:     const s = start[1] * w + start[0], t = goal[1] * w + goal[0];
642:     const prev = new Int32Array(w * h).fill(-1);
643:     const seen = new Uint8Array(w * h);
644:     const q = new Int32Array(w * h);
