650:       for (let k = 0; k < 4; k++) {
651:         const nx = cx + (k === 0 ? 1 : k === 1 ? -1 : 0);
652:         const nz = cz + (k === 2 ? 1 : k === 3 ? -1 : 0);
653:         if (nx < 0 || nz < 0 || nx >= w || nz >= h) continue;
654:         const ni = nz * w + nx;
655:         if (seen[ni] || !PATH.walk[ni]) continue;
656:         seen[ni] = 1; prev[ni] = cur; q[tail++] = ni;
657:       }
